35	const PROCESSING_FEE = 5;
36	
37	/**
38	 * The first-insurance surcharge is +10%, applied as the exact ratio 11/10
39	 * rather than a 1.1 multiplier. Floating-point `100 * 1.1` is
40	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
41	 * instead of 115 G. Multiplying before dividing keeps the arithmetic exact.
42	 */
43	const FIRST_INSURANCE_NUMERATOR = 11;
44	const FIRST_INSURANCE_DENOMINATOR = 10;
45	
46	const applyFirstInsuranceSurcharge = (amount: number): number =>
47	  (amount * FIRST_INSURANCE_NUMERATOR) / FIRST_INSURANCE_DENOMINATOR;
48	
49	/** All rounding is in the MHPCO's favor — always up. */
50	const roundInMHPCOsFavor = Math.ceil;
51	
52	const sumBasePremiums = (items: InsuredItem[]): number =>
53	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
54	
55	const quotePremium = (step: Step): QuoteResult => {
56	  const base = sumBasePremiums(step.items ?? []);
57	
58	  return {
59	    premium: roundInMHPCOsFavor(applyFirstInsuranceSurcharge(base)) +
60	      PROCESSING_FEE,
61	  };
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioResults => ({
65	  results: scenario.steps.map(quotePremium),
66	});
